import itertools
from collections import defaultdict
c=load_corpus()
def loss(ch): return ch['mean_test_mse'] if ch['mean_test_mse'] is not None else ch['mean_test_ce']
def score(ch): return sum(ch['layer_norm'] or [])+ (1 if ch['residual'] else 0)
def same(a,b): return (a['optimizer'],a['lr'],a['training_steps'],a.get('momentum'))==(b['optimizer'],b['lr'],b['training_steps'],b.get('momentum'))
for fam in ['univariate_regression','multivariate_regression','synthetic_tabular_classification','xor_classification','spiral_classification']:
    res=defaultdict(lambda:[0,0]); res2=defaultdict(lambda:[0,0]); r=[0,0]
    for q in c:
        if q['family']!=fam: continue
        ch=[x for x in q['choices'] if x['model_type']=='mlp']
        for a,b in itertools.combinations(ch,2):
            if not same(a,b): continue
            d=score(a)-score(b)
            if d==0:
                dd=a['depth']-b['depth']
                if dd==0: continue
                w=(loss(a)<loss(b))==(dd>0); res2[min(abs(dd),3)][0 if w else 1]+=1; continue
            w=(loss(a)<loss(b))==(d>0); res[min(abs(d),4)][0 if w else 1]+=1
        for a,b in itertools.permutations(ch,2):
            if same(a,b) and sum(a['layer_norm'])>=2 and not a['residual'] and b['residual'] and sum(b['layer_norm'])==0:
                r[0 if loss(a)<loss(b) else 1]+=1
    print(fam,'scorediff',dict(res),'tie-depth',dict(res2),'LN>=2plain vs resNoLN',r)
