import itertools, math
from collections import defaultdict
c=load_corpus()
def loss(ch): return ch['mean_test_mse'] if ch['mean_test_mse'] is not None else ch['mean_test_ce']
def delta(ch):
    o=ch['optimizer']; lr=ch['lr']; T=ch['training_steps']; m=ch.get('momentum') or 0
    if o in ('Adam','AdamW','RMSprop'): return lr*T
    if o=='Adagrad': return 2*lr*math.sqrt(T)
    if o=='SGD':
        g=0.003 if 'bigram' in ch.get('_fam','') else (0.03 if ch['loss']=='mse' and m>0 else 0.01)
        return lr*T*g/(1-m)
    return None
res=defaultdict(lambda:[0,0])
for q in c:
    if q['type']=='architecture_only': continue
    for x in q['choices']: x['_fam']=q['family']
    for a,b in itertools.combinations(q['choices'],2):
        da,db=delta(a),delta(b)
        if not da or not db or da==db: continue
        r=max(da,db)/min(da,db)
        k='1-1.5' if r<1.5 else '1.5-4' if r<4 else '>=4'
        w=(loss(a)<loss(b))==(da>db); res[(q['type'],k)][0 if w else 1]+=1
for k in sorted(res): print(k,res[k], round(res[k][0]/sum(res[k]),2))
